import{_ as t,o as e,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ38 求小球落地5次后所经历的路程和第5次反弹的高度","description":"中等 通过率：41.50% 时间限制：1秒 空间限制：32M 知识点 模拟 思维 描述 假设一个球从任意高度自由落下，每次落地后反跳回原高度的一半; 再落下, 求它在第5次落地时，共经历多少米?第5次反弹多高？ 数据范围：输入的小球初始高度满足 1≤ n ≤1000 ，且保证是一。","frontmatter":{"title":"HJ38 求小球落地5次后所经历的路程和第5次反弹的高度","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：41.50% 时间限制：1秒 空间限制：32M 知识点 模拟 思维 描述 假设一个球从任意高度自由落下，每次落地后反跳回原高度的一半; 再落下, 求它在第5次落地时，共经历多少米?第5次反弹多高？ 数据范围：输入的小球初始高度满足 1≤ n ≤1000 ，且保证是一。","sidebarWeight":36,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为入门题/HJ38 求小球落地5次后所经历的路程和第5次反弹的高度.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ38 求小球落地5次后所经历的路程和第5次反弹的高度.md","filePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ38 求小球落地5次后所经历的路程和第5次反弹的高度.md"}'),i={name:"posts/前端面试与实战/03-算法训练/华为入门题/HJ38 求小球落地5次后所经历的路程和第5次反弹的高度.md"};function n(h,a,l,_,s,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<div><h1 id="hj38-求小球落地5次后所经历的路程和第5次反弹的高度" tabindex="-1">HJ38 求小球落地5次后所经历的路程和第5次反弹的高度 <a class="header-anchor" href="#hj38-求小球落地5次后所经历的路程和第5次反弹的高度" aria-label="Permalink to &quot;HJ38 求小球落地5次后所经历的路程和第5次反弹的高度&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ38 求小球落地5次后所经历的路程和第5次反弹的高度”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：41.50% 时间限制：1秒 空间限制：32M 知识点==模拟====思维== <strong>描述</strong> 假设一个球从任意高度自由落下，每次落地后反跳回原高度的一半; 再落下, 求它在第5次落地时，共经历多少米?第5次反弹多高？</p></blockquote><p>数据范围：输入的小球初始高度满足 1≤<em>n</em>≤1000 ，且保证是一个整数 <strong>输入描述：</strong> 输入起始高度，int型 <strong>输出描述：</strong> 分别输出第5次落地时，共经过多少米以及第5次反弹多高。 注意：你可以认为你输出保留六位或以上小数的结果可以通过此题。 <strong>示例1</strong> 输入： 1 ==复制== 输出： 2.8750.03125</p><ul><li>只遍历四次，最后一次特殊处理</li><li>每一次遍历，都是先加上一次加弹后落地的高度，然后将这次弹起的高度除以2，再加上这一次落地后回弹的高度；</li><li>由于题目中只要计算第五次落点为止的高度，最后的回弹高度不加上去 下面是实现这个计算的Python代码： def ball_bounce(h):</li></ul><h1 id="初始化总经过的距离和当前高度" tabindex="-1">初始化总经过的距离和当前高度 <a class="header-anchor" href="#初始化总经过的距离和当前高度" aria-label="Permalink to &quot;初始化总经过的距离和当前高度&quot;">​</a></h1><p>total_distance = 0 current_height = h</p><h1 id="对于前4次落地-球都会再次反弹" tabindex="-1">对于前4次落地，球都会再次反弹 <a class="header-anchor" href="#对于前4次落地-球都会再次反弹" aria-label="Permalink to &quot;对于前4次落地，球都会再次反弹&quot;">​</a></h1><p>for _ in range(4):</p><h1 id="球下落的距离加上当前高度" tabindex="-1">球下落的距离加上当前高度 <a class="header-anchor" href="#球下落的距离加上当前高度" aria-label="Permalink to &quot;球下落的距离加上当前高度&quot;">​</a></h1><p>total_distance += current_height</p><h1 id="球反弹的高度是当前高度的一半" tabindex="-1">球反弹的高度是当前高度的一半 <a class="header-anchor" href="#球反弹的高度是当前高度的一半" aria-label="Permalink to &quot;球反弹的高度是当前高度的一半&quot;">​</a></h1><p>current_height /= 2</p><h1 id="球反弹上去的距离也要加上" tabindex="-1">球反弹上去的距离也要加上 <a class="header-anchor" href="#球反弹上去的距离也要加上" aria-label="Permalink to &quot;球反弹上去的距离也要加上&quot;">​</a></h1><p>total_distance += current_height</p><h1 id="第5次落地-只需加上最后一次下落的距离" tabindex="-1">第5次落地，只需加上最后一次下落的距离 <a class="header-anchor" href="#第5次落地-只需加上最后一次下落的距离" aria-label="Permalink to &quot;第5次落地，只需加上最后一次下落的距离&quot;">​</a></h1><p>total_distance += current_height</p><h1 id="第5次反弹的高度" tabindex="-1">第5次反弹的高度 <a class="header-anchor" href="#第5次反弹的高度" aria-label="Permalink to &quot;第5次反弹的高度&quot;">​</a></h1><p>fifth_bounce_height = current_height / 2 return total_distance, fifth_bounce_height</p><h1 id="读取输入的起始高度" tabindex="-1">读取输入的起始高度 <a class="header-anchor" href="#读取输入的起始高度" aria-label="Permalink to &quot;读取输入的起始高度&quot;">​</a></h1><p>initial_height = int(input())</p><h1 id="计算并打印结果" tabindex="-1">计算并打印结果 <a class="header-anchor" href="#计算并打印结果" aria-label="Permalink to &quot;计算并打印结果&quot;">​</a></h1><p>total_distance, fifth_bounce_height = ball_bounce(initial_height) print(&quot;{:.6f}&quot;.format(total_distance)) print(&quot;{:.6f}&quot;.format(fifth_bounce_height))</p><p>这段代码首先计算了从第1次落地到第5次落地时小球所经过的总距离，然后计算了第5次反弹的高度。每次反弹高度都是前一次高度的一半，每次落地后经过的距离包括下落和反弹的距离（除了最后一次落地，因为它不再上升）。最后，代码输出了第5次落地时总经过的距离和第5次反弹的高度，结果保留了六位小数。</p></div>',1)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
